"""
Messy real-world toolpath — winding-down bead, viewer vs data artifacts

A raw G-code snippet from a 5-axis (A45) deposition path where the extrusion
"winds down": long ~470 mm raster strokes joined by tight little U-turn /
wipe loops, with bead width falling off toward the end. The bead width is
derived from the cumulative extrusion column E:

    width_mm = dE_cc * 1000 / (bead_height_mm * dL_mm)

The interesting bit is the wipe loops. Their local turn radius (~5-8 mm) is
smaller than the bead is wide (up to ~15 mm), so a centre-line-swept tube
*must* fold there — the outer wall wraps past the centre. That's a geometric
inevitability of the representation, not a shading bug. The question this
example lets you study: how much of the ugliness is the folding data, and
how much is the *viewer's* handling of it?

Two knobs to compare on the SAME geometry:

- ``strand_collapse=True`` turns the self-intersecting fold fans on tight
  inside corners into clean creases (the footprint is preserved). Press
  **S** in the viewer to toggle it on/off and watch the wipe loops.
- A plain polyline of the spine is drawn underneath so the true path is
  always visible regardless of how the tube folds.

Run: uv run python examples/29_messy_toolpath_winddown.py
"""

import re

import numpy as np

from threejs_viewer import viewer

BEAD_HEIGHT = 3.0  # mm (given)

# Deposition is tilted (the A45 block): the bead normal is not world-vertical
# but tilted 45 deg about the +X axis (the A45 block). The height axis of the
# tube must follow it, otherwise every ring is built flat-to-Z and the bead
# shears. Rotating +Z by TILT about +X gives up = (0, -sin, cos); the sign
# (-Y, +Z) is the nozzle-side normal recovered from the raster step direction
# (0, -1, -1).
TILT_DEG = 45.0
_t = np.radians(TILT_DEG)
UP_VECTOR = [0.0, -np.sin(_t), np.cos(_t)]  # -> [0, -0.707, 0.707]

# --- The raw messy input (exact G-code lines, X/Y/Z/A/B/C/E) ---------------
# E is cumulative extrusion volume in cc; A45 tilts the whole block 45 deg.
